"""Render the extended-region methods note from the built data and checks."""
from pathlib import Path
import json,html
P=Path(__file__).resolve().parents[1]
stats=json.loads((P/'regions/inside-ring3-stats.json').read_text(encoding='utf-8'))
checks=json.loads((P/'rr3_model_checks.json').read_text(encoding='utf-8')) if (P/'rr3_model_checks.json').exists() else None
def f(n):return f'{n:,.0f}'.replace(',',' ')
rows=[('Diện tích khung phủ, có dải đệm',f(stats['approx_bbox_km2'])+' km²'),('Nút hình học / giao lộ từ 3 láng giềng',f(stats['nodes'])+' / '+f(stats['junctions'])),('Đoạn có hướng (hai chiều đếm hai đoạn)',f(stats['directed_links'])),('Nút đèn suy ra từ OSM',f(stats['signals'])),('Điểm đi–đến tổng hợp',f(stats['portals'])),('Ô dân cư hiển thị khoảng 300 m',f(stats['population_cells']))]
table='<table>'+''.join('<tr><th>'+a+'</th><td>'+b+'</td></tr>' for a,b in rows)+'</table>'
test_html='<p>Chưa có kết quả kiểm tra vùng mở rộng.</p>'
if checks:
 test_html='<p>'+str(len(checks['checks']))+' kiểm tra đạt. Lần chạy tái lập dùng '+f(checks['tripCount'])+' chuyến/ngày, mã nhu cầu <code>'+checks['fingerprint']+'</code>. Đây là kiểm tra phần mềm, không phải đối chiếu thực địa.</p><ul>'+''.join('<li>'+html.escape(x['name'])+'</li>' for x in checks['checks'])+'</ul><p><a href="rr3_model_checks.json">Kết quả chi tiết và hai bộ chỉ số</a> · <a href="rr3_example_design.json">Phương án thử đường + nhánh</a></p>'
body='''<p><a href="index.html">← Mở giả lập</a> · <a href="report.html">Thí nghiệm lịch sử vùng nhỏ</a></p>
<h1>Mở rộng vùng Vành đai 3</h1><p>Mạng đường thật, nhu cầu tổng hợp. Chưa hiệu chỉnh hoặc kiểm định bằng số đếm giao thông thực địa.</p>
<h2>Phạm vi và dữ liệu</h2><p>Khung [105.74, 20.94, 106.00, 21.19] phủ vùng trong Vành đai 3 và một dải đệm để thấy các đường tiếp cận. Diện tích ghi dưới đây là diện tích khung, không phải diện tích bên trong một đa giác ranh giới chính thức. Phần phía bắc của tuyến vành đai có yếu tố quy hoạch; trang không vẽ ra một đường bao pháp lý.</p>'''+table+'''
<p><a href="https://download.geofabrik.de/asia/vietnam.html">Geofabrik / OpenStreetMap</a>, snapshot 27/10/2026 21:23:59 UTC: hình học, kết nối, đường một chiều, làn đường khi có, loại đường, cầu/hầm/layer và một số hạn chế loại xe. Giữ mạng liên thông mạnh cho ô tô; chọn điểm đi–đến nằm trong phần liên thông chung với xe máy. Có đường dân cư, living street và các đường nối; loại bỏ đường chỉ dành cho người đi bộ/xe đạp, service/track, đường cấm chung và thành phần bị cô lập. Vì vậy đây không phải kiểm kê đầy đủ mọi ngõ và đường vào nhà.</p>
<p>815 nút đèn là các giao lộ được gán từ điểm traffic_signals OSM trong bán kính tối đa 80 m. Chu kỳ 90 giây và pha đèn là giả định. Không có danh mục bộ điều khiển, thời lượng đèn, làn rẽ hay cấm rẽ đầy đủ từ cơ quan giao thông. OSM motorcycle/motorbike=no và motorway chặn xe máy; các hạn chế phụ thuộc thời gian và quan hệ turn restriction chưa được mô hình hóa đầy đủ.</p>
<p><a href="https://hub.worldpop.org/geodata/summary?id=6449">WorldPop 2020</a>, DOI 10.5258/SOTON/WP00645, CC BY 4.0: dữ liệu dân cư ước tính trên ô gốc 3 giây cung (~100 m), được cộng 3×3 ô thành ô hiển thị ~300 m. Mật độ chia tổng dân cư cho diện tích địa lý của ô. Không phải dân số đo đạc năm 2026. Các hình mặt nước chỉ lấy polygon đóng sẵn trong snapshot, không phải lớp thủy hệ đầy đủ.</p>
<h2>Nhu cầu và so sánh</h2><p>81 điểm đi–đến được chọn gần tâm lưới 9×9 trên vùng phủ và có đường đi cho cả hai loại xe. Khi bật dân cư, xác suất điểm đi dùng tổng dân cư lân cận với trọng số Gaussian bán kính tham số 1.200 m; điểm đến lấy ngẫu nhiên trong các điểm còn lại cách ít nhất 1 km. Đây là phương pháp tạo OD giả định, không suy ra luồng đi làm từ mật độ dân cư. Mặc định 45.000 chuyến/ngày, 80% xe máy và các trọng số theo giờ đều là đầu vào thử nghiệm có thể sửa.</p>
<p>Mỗi lần so sánh chỉ tạo một tập chuyến rồi đưa cùng các đối tượng chuyến cho hai động cơ: cùng OD, loại xe và giờ xuất phát. Đường đi được tính lại trên từng mạng. Đường mới và nhánh thêm cạnh truy nhập, chuyển hướng, nút giao và xung đột; giao cắt mới cùng mức có thể bật/tắt. Không tự nối giao cắt hình học với đường có layer khác 0, cầu/hầm hay motorway; điểm đầu/cuối nối do người vẽ chọn rõ ràng.</p>
<p>Chế độ vẽ giữ nguyên nhu cầu theo yêu cầu so sánh hiện tại. Các thí nghiệm S3/S4 trong báo cáo cũ mới có nhu cầu phát sinh; không được đọc kết quả của chế độ này như dự báo nhu cầu cảm ứng. Vị trí chấm xe được minh họa, tối đa 350 chấm mỗi bản đồ ở vùng lớn, còn toàn bộ xe vẫn được tính trong chỉ số.</p>
<p>Chạy 24 giờ phát sinh + 1 giờ xả. Hoàn thành = xe đã đến đích; chờ gồm cả xe chưa xong và xe còn ngoài mạng; spillback = tổng thời gian đoạn bị chặn bởi dung tích đoạn tiếp theo; throughput trong bảng là xe đến đích trong 15 phút gần nhất quy đổi theo giờ. Hàng đợi có dung tích hữu hạn theo PCU và FIFO. Bộ lập lịch chỉ đánh thức nút có xe có thể được phục vụ; cache bản đồ và tính toán nền giúp giao diện tiếp tục hoạt động khi chạy.</p>
<h2>Kiểm tra và giới hạn áp dụng</h2>'''+test_html+'''
<p>Ba fixture JavaScript/Python và bộ lập lịch mới khớp ở sai số số thực dưới 10⁻⁶. Kiểm tra vùng lớn đối chiếu bộ lập lịch với quét toàn mạng, định tuyến theo loại xe, vẽ ngoài vùng cũ, thêm/xóa nhánh, sử dụng đường mới, bảo toàn xe và giới hạn dung tích. Các kiểm tra này xác nhận logic triển khai; chúng không xác nhận tốc độ, năng lực, tỷ lệ xe hay OD thực tế của Hà Nội.</p>
<p><strong>124 thí nghiệm trong báo cáo gốc chỉ áp dụng cho vùng Láng–Giảng Võ khoảng 8,15 km².</strong> Không chuyển các kết luận hoặc khoảng tin cậy đó sang vùng Vành đai 3. Cần số đếm theo nút/giờ/loại xe, thời lượng tín hiệu, đo hành trình và OD độc lập để hiệu chỉnh rồi kiểm định trên thời gian hoặc vị trí chưa dùng để hiệu chỉnh.</p>
<h2>Tái lập và ghi công</h2><p><a href="data/rr3_provenance.json">Nguồn, ngày trích xuất và SHA-256</a> · <a href="data/rr3_osm_snapshot.json.gz">Snapshot OSM vùng nghiên cứu</a> · <a href="data/rr3_worldpop_2020_clip.tif">Raster dân cư gốc đã cắt</a> · <a href="regions/inside-ring3-stats.json">Thống kê mạng</a> · <a href="https://github.com/loveless2001/hanoi-traffic-lab">Mã nguồn và hướng dẫn</a></p>
<p>© OpenStreetMap contributors / Geofabrik — ODbL 1.0. WorldPop / University of Southampton — CC BY 4.0. Mã nguồn MIT. Các đường tự vẽ không được xác nhận khả thi về xây dựng.</p>'''
css='body{font:16px/1.65 system-ui;margin:0;background:#fafbfc;color:#20313c}main{max-width:920px;margin:auto;padding:28px}h1{font-size:30px}h2{font-size:21px;margin-top:32px}a{color:#087e8b}table{border-collapse:collapse;width:100%}th,td{border-bottom:1px solid #ccd5d9;padding:9px;text-align:left}th{font-weight:500}code{overflow-wrap:anywhere}@media(prefers-color-scheme:dark){body{background:#151a21;color:#e3e9ed}a{color:#51cad0}}'
(P/'region-report.html').write_text('<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vành đai 3: dữ liệu và kiểm tra</title><style>'+css+'</style><main>'+body+'</main></html>',encoding='utf-8')
# Keep the old experiment report explicit about its historical small extent.
banner='<aside><strong>Bản đồ đã mở rộng đến vùng Vành đai 3.</strong> 124 thí nghiệm dưới đây vẫn thuộc vùng Láng–Giảng Võ 8,15 km². <a href="region-report.html">Đọc dữ liệu, giả định và kiểm tra của vùng mở rộng</a>.</aside>'
old=P/'report.html'
if old.exists():
 text=old.read_text(encoding='utf-8')
 if 'Đọc dữ liệu, giả định và kiểm tra của vùng mở rộng' not in text:old.write_text(text.replace('<main>','<main>'+banner,1),encoding='utf-8')
print('Built region-report.html')
